                "message": f"File exists but is empty: {filename}"
            })
            failed_count += 1
            continue

        # File exists and is non-empty, pass the check
        results.append({
            "check_name": filename,
            "passed": True,
            "message": "File exists and is non-empty"
        })
        passed_count += 1

    # Write the validation summary to the output file
    output_path = "outputs/t14_validation_summary.json"
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(results, f, indent=2)

    return results

if __name__ == "__main__":
    results = run_checks()
    print(f"Validation completed. Passed: {passed_count}, Failed: {failed_count}")
    sys.exit(0 if failed_count == 0 else 1)
